// 原因、补充或重新提交经过。待处理、结果缺失或无法识别的残留记录不被认定为退回；
// 有轮次的正常退回不重复增加记录。查询不写入退回轮次，补充重新提交仍明确报错。
func TestItemJourneyReturnedWithoutRounds(t *testing.T) {
	svc := openLegacyService(t, legacyReturnedWithoutRoundsRaw)

	// I001：有处理人与真实处理时间（早于发起时刻），退回按实际时刻进入时间线。
	j1, err := svc.ItemJourney("I001")
	if err != nil {
		t.Fatalf("journey I001: %v", err)
	}
	if got := journeyKinds(j1); joinStrings(got) != "created,return-incomplete,handover-init" {
		t.Fatalf("有真实时间的退回应按实际时刻排序：%v", got)
	}
	rev := j1.Events[1]
	if !rev.TimeKnown || !rev.HistoryIncomplete || rev.Operator != "赵六" ||
		rev.HandoverID != "H001" || rev.FromShift != "S001" || rev.ToShift != "S002" {
		t.Fatalf("退回事件应带出交接编号、两班、处理人与时间：%+v", rev)
	}
	text1 := FormatItemJourney(j1)
	for _, want := range []string{
		"交接 H001（S001 -> S002）退回 操作人=赵六（退回历史不完整：缺少退回轮次记录，退回原因未记录）",
		"2026-10-02 09:30:00 +08:00",
		"当前结果：退回（等待交班人补充）",
	} {
		if !strings.Contains(text1, want) {
			t.Fatalf("I001 展示缺少 %q：\n%s", want, text1)
		}
	}
	for _, bad := range []string{"第1次退回", "原因=缺轮次已退回", "重新提交", "0001-01-01"} {
		if strings.Contains(text1, bad) {
			t.Fatalf("I001 展示不应出现 %q：\n%s", bad, text1)
		}
	}

	// I002：处理时间为零值，显示未记录，排在有真实时间的发起交接之后，
	// 不拿交接发起时间补齐。
	j2, err := svc.ItemJourney("I002")
	if err != nil {
		t.Fatalf("journey I002: %v", err)
	}
	if got := journeyKinds(j2); joinStrings(got) != "created,handover-init,return-incomplete" {
		t.Fatalf("未记录时间的退回应排在有真实时间的经过之后：%v", got)
	}
	if j2.Events[2].TimeKnown {
		t.Fatalf("零值处理时间不能被补齐：%+v", j2.Events[2])
	}
	text2 := FormatItemJourney(j2)
	for _, want := range []string{
		"未记录 交接 H001（S001 -> S002）退回 操作人=赵六（退回历史不完整：缺少退回轮次记录，退回原因未记录）",
		"处理时间=未记录", "等待交班人补充",
	} {
		if !strings.Contains(text2, want) {
			t.Fatalf("I002 展示缺少 %q：\n%s", want, text2)
		}
	}
	if strings.Contains(text2, "0001-01-01") {
		t.Fatalf("零值时间不能显示成公元元年：\n%s", text2)
	}

	// I003：姓名缺失但时间真实（+09:00 与发起 +08:00 表示同一时刻）：时间保留
	// 时区展示，操作人标未记录；同一时刻同一交接内发起在前、退回在后。
	j3, err := svc.ItemJourney("I003")
	if err != nil {
		t.Fatalf("journey I003: %v", err)
	}
	if got := journeyKinds(j3); joinStrings(got) != "created,handover-init,return-incomplete" {
		t.Fatalf("同一时刻应保持发起在前、退回在后：%v", got)
	}
	if !j3.Events[2].TimeKnown || j3.Events[2].Operator != "" {
		t.Fatalf("缺姓名不影响真实时间：%+v", j3.Events[2])
	}
	text3 := FormatItemJourney(j3)
	for _, want := range []string{
		"2026-10-02 11:00:00 +09:00 交接 H001（S001 -> S002）退回 操作人=未记录（退回历史不完整",
		"处理人=未记录；处理时间=2026-10-02 11:00:00 +09:00",
	} {
		if !strings.Contains(text3, want) {
			t.Fatalf("I003 展示缺少 %q：\n%s", want, text3)
		}
	}

	// I004：姓名与时间都缺失，仍呈现退回，两者分别标为未记录。
	j4, err := svc.ItemJourney("I004")
	if err != nil {
		t.Fatalf("journey I004: %v", err)
	}
	if got := journeyKinds(j4); joinStrings(got) != "created,handover-init,return-incomplete" {
		t.Fatalf("I004 经过不正确：%v", got)
	}
	text4 := FormatItemJourney(j4)
	for _, want := range []string{
		"退回 操作人=未记录（退回历史不完整",
		"处理人=未记录；处理时间=未记录",
	} {
		if !strings.Contains(text4, want) {
			t.Fatalf("I004 展示缺少 %q：\n%s", want, text4)
		}
	}

	// I005：待处理即使残留处理人、处理时间，也不能认定发生退回。
	j5, err := svc.ItemJourney("I005")
	if err != nil {
		t.Fatalf("journey I005: %v", err)
	}
	if got := journeyKinds(j5); joinStrings(got) != "created,handover-init" {
		t.Fatalf("待处理残留不能产生退回经过：%v", got)
	}
	text5 := FormatItemJourney(j5)
	for _, bad := range []string{"退回", "钱七"} {
		if strings.Contains(text5, bad) {
			t.Fatalf("待处理残留不能显示成退回或带出残留处理人 %q：\n%s", bad, text5)
		}
	}

	// I006：已有退回轮次的事项仍是逐轮退回，不再增加一条相同记录，也不提示不完整。
	j6, err := svc.ItemJourney("I006")
	if err != nil {
		t.Fatalf("journey I006: %v", err)
	}
	if got := journeyKinds(j6); joinStrings(got) != "created,handover-init,return" {
		t.Fatalf("有轮次的退回应只展示逐轮记录：%v", got)
	}
	text6 := FormatItemJourney(j6)
	for _, want := range []string{"第1次退回 操作人=李四 原因=正常原因"} {
		if !strings.Contains(text6, want) {
			t.Fatalf("I006 展示缺少 %q：\n%s", want, text6)
		}
	}
	if strings.Contains(text6, "退回历史不完整") {
		t.Fatalf("有轮次的退回不应提示历史不完整：\n%s", text6)
	}

	// I007/I008：结果缺失或无法识别，即使残留姓名与时间也不认定发生退回。
	for _, id := range []string{"I007", "I008"} {
		j, err := svc.ItemJourney(id)
		if err != nil {
			t.Fatalf("journey %s: %v", id, err)
		}
		if got := journeyKinds(j); joinStrings(got) != "created,handover-init" {
			t.Fatalf("%s 残留记录不能产生退回经过：%v", id, got)
		}
		if strings.Contains(FormatItemJourney(j), "退回历史不完整") {
			t.Fatalf("%s 不应提示退回历史不完整", id)
		}
	}

	// 查询不写入退回轮次：查询后补充并重新提交仍按现有规则明确报错，
	// 不能把查询时的提示当作已补齐的退回记录；状态、归属也不变。
	if _, err := svc.ItemJourney("I001"); err != nil {
		t.Fatalf("repeat journey: %v", err)
	}
	h, err := svc.GetHandover("H001")
	if err != nil {
		t.Fatalf("get handover: %v", err)
	}
	var e1 *HandoverEntry
	for i := range h.Entries {
		if h.Entries[i].ItemID == "I001" {
			e1 = &h.Entries[i]
		}
	}
	if e1 == nil || e1.Status != EntryReturned || len(e1.Rounds) != 0 {
		t.Fatalf("查询不能写入退回轮次或改变当前结果：%+v", e1)
	}
	if _, err := svc.ResubmitReturned("H001", "I001", "张三", "事后补充"); !errors.Is(err, ErrHandoverState) {
		t.Fatalf("缺少退回轮次时重新提交应报状态错误，got %v", err)
	}
	h2, _ := svc.GetHandover("H001")
	for i := range h2.Entries {
		if h2.Entries[i].ItemID == "I001" {
			e1 = &h2.Entries[i]
		}
	}
	if e1.Status != EntryReturned || len(e1.Rounds) != 0 {
		t.Fatalf("失败的重新提交不能补造轮次：%+v", e1)
	}
	it, _ := svc.GetItem("I001")
	if it.CurrentShiftID != "S001" {
		t.Fatalf("查询与失败重新提交不能改变事项归属：%s", it.CurrentShiftID)
	}
}

package handover

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

const displayTime = "2006-01-02 15:04:05 -07:00"

func fmtTime(t time.Time) string { return t.Format(displayTime) }

func fmtTimePtr(t *time.Time) string {
	if t == nil {
		return "-"
	}
	return fmtTime(*t)
}

// FormatShift 格式化班次摘要。
func FormatShift(sh Shift) string {
	state := "进行中"
	if sh.Closed {
		state = "已结束 " + fmtTimePtr(sh.ClosedAt)
	}
	return fmt.Sprintf("%s  岗位=%s  负责人=%s  %s ~ %s  [%s]",
		sh.ID, sh.Position, sh.Owner, fmtTime(sh.Start), fmtTime(sh.End), state)
}

// FormatItem 格式化事项及其关闭情况与历史。
func FormatItem(it Item) string {
	var b strings.Builder
	writeItemHeader(&b, it)
	if len(it.Events) > 0 {
		b.WriteString("  历史：\n")
		for _, ev := range it.Events {
			who := ""
			if ev.Operator != "" {
				who = " 操作人=" + ev.Operator
			}
			detail := ""
			if ev.Detail != "" {
				detail = " " + ev.Detail
			}
			fmt.Fprintf(&b, "    - %s %s%s%s\n", fmtTime(ev.At), ev.Kind, who, detail)
		}
	}
	return b.String()
}

// writeItemHeader 输出事项的最新内容、严重程度、限制条件、后续负责人、
// 当前所在班次、关闭情况和流经班次。
func writeItemHeader(b *strings.Builder, it Item) {
	state := "未关闭"
	if it.Closed {
		state = formatClosedState("已关闭", it.CloseOperator, it.ClosedAt)
	}
	fmt.Fprintf(b, "%s  严重程度=%s  当前班次=%s  原始班次=%s  [%s]\n",
		it.ID, it.Severity.Label(), it.CurrentShiftID, it.OriginShiftID, state)
	fmt.Fprintf(b, "  内容：%s\n", it.Content)
	fmt.Fprintf(b, "  限制条件：%s\n", dashIfEmpty(it.Constraints))
	fmt.Fprintf(b, "  后续负责人：%s\n", it.FollowOwner)
	fmt.Fprintf(b, "  流经班次：%s\n", strings.Join(it.ShiftIDs, " -> "))
}

func dashIfEmpty(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

// whoIfRecorded 展示操作人，未记录时明确标为未记录，不以其他人代替。
func whoIfRecorded(s string) string {
	if s == "" {
		return "未记录"
	}
	return s
}

// fmtTimePtrIfRecorded 展示时间指针，缺失时明确标为未记录。
func fmtTimePtrIfRecorded(t *time.Time) string {
	if t == nil {
		return "未记录"
	}
	return fmtTimeIfRecorded(*t)
}

// fmtTimeIfRecorded 展示时间值，旧数据零值（0001-01-01T00:00:00Z）时
// 明确标为未记录，不显示公元元年日期。
func fmtTimeIfRecorded(t time.Time) string {
	if t.IsZero() {
		return "未记录"
	}
	return fmtTime(t)
}

// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
func fmtProcessedAtIfRecorded(t *time.Time) string {
	if t == nil || t.IsZero() {
		return "未记录"
	}
	return fmtTime(*t)
}

// formatClosedState 是事项关闭信息在展示层的统一解读，item-show 的最新状态与
// shift-show 的当前事项、结束时记录、最新状态对照共用，保证同一份关闭信息在
// 各处解释一致。prefix 为“已关闭”或“结束时已关闭”。
//
// 只按已保存事实展示，不补齐、不推测：
//   - 事项保存的关闭状态为已关闭时，结论固定为已关闭，不能因为关闭人或关闭
//     时间缺失而改成未关闭；保存状态为未关闭时由调用方另行展示，残留的关闭人
//     或时间不作为一次有效关闭；
//   - 关闭人未保存或为空显示“未记录”；关闭时间未保存（nil）或为旧数据零值
//     （0001-01-01T00:00:00Z）同样显示“未记录”，不显示横线或公元元年日期；
//   - 姓名与时间分别判断：有姓名无时间保留姓名并指出关闭时间未记录，有真实
//     时间无姓名保留带时区的实际时间并指出关闭人未记录，缺一个不隐藏另一个，
//     也不以班次负责人或处理经过中的信息代替；
//   - 两者都有记录时沿用原有“姓名 于 时间”格式。
func formatClosedState(prefix, operator string, closedAt *time.Time) string {
	hasOperator := operator != ""
	hasTime := closedAt != nil && !closedAt.IsZero()
	switch {
	case hasOperator && hasTime:
		return fmt.Sprintf("%s（%s 于 %s）", prefix, operator, fmtTime(*closedAt))
	case hasOperator:
		return fmt.Sprintf("%s（关闭人 %s，关闭时间未记录）", prefix, operator)
	case hasTime:
		return fmt.Sprintf("%s（关闭人未记录，关闭时间 %s）", prefix, fmtTime(*closedAt))
	default:
		return prefix + "（关闭人未记录，关闭时间未记录）"
	}
}

// currentProcessing 返回交接单项当前处理结果的处理人与处理时间展示，是
// 交接清单（handover-show、shift-show 内嵌清单与末尾结果说明）和事项处理
// 经过查询（item-show）共用的同一条业务规则。
//
// 是否处理过以已保存的处理结果（状态）为准，与处理时间是否保存无关：确认
// 接收、继续跟踪与退回都属于已经发生的处理，缺少处理时间不能使它们变成待
// 处理；真正待处理（含退回后已补充重新提交、等待接班人再次处理）的事项，
// 处理人与处理时间都显示尚未处理，即使旧记录残留姓名或时间也不显示成已处理。
//
// 已处理时处理人与处理时间各自独立展示：人名有值展示原姓名、缺失明确标为
// 未记录；时间有真实值沿用带时区格式、缺失或为旧数据零值
// （0001-01-01T00:00:00Z）同样标为未记录。缺少其中一个不能隐藏另一个，
// 也不以班次负责人、交接发起时间或退回历史中的信息代替。结果为空或无法
// 识别的记录同样按各自已保存的姓名与时间展示，不据以推测接收结果。
func currentProcessing(e HandoverEntry) (operator, processedAt string) {
	if e.Status == EntryPending {
		return "尚未处理", "尚未处理"
	}
	return whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt)
}

// returnRoundView 是一轮退回历史在展示层的统一解读。交接查询
// （handover-show，及 shift-show 报告内嵌的交接清单）与班次报告末尾
// “各项交接当前结果”两处共用同一份判断，只保留各自的措辞、缩进与
// 字段次序——统一维护的是共同规则，不是把两处改成同一种文本。
type returnRoundView struct {
	Seq            int
	ReturnedAt     string // 退回时间：真实值用带时区格式；缺失或零值显示未记录
	ReturnOperator string // 退回人：有值保留原姓名，缺失显示未记录
	Reason         string // 该轮保存的退回原因，原样展示

	HasSupplement      bool   // 该轮是否保存了非空补充说明；没有就不产生补充段落
	Supplement         string // 该轮保存的补充说明
	SupplementOperator string // 补充人：缺失显示未记录
	SupplementAt       string // 补充时间：缺失（nil）或零值显示未记录

	Resubmitted   bool   // 该轮是否保存了重新提交时间（旧数据零值也算已重新提交）
	ResubmittedAt string // 重新提交时间：零值显示未记录；未保存时不展示该行
}

// viewReturnRound 按共同规则解读一轮已保存的退回历史。它只做展示判断，
// 不补齐、不推测：
//   - 姓名有值保留原姓名、缺失显示未记录；时间缺失或为旧数据零值
//     （0001-01-01T00:00:00Z）显示未记录，真实时间沿用带时区格式，
//     姓名与时间各自独立判断，缺一个不隐藏另一个；
//   - 不用班次负责人、交接发起时间、当前处理人或其他轮次的资料补齐
//     本轮记录；
//   - 该轮没有非空补充说明时不产生补充段落；没有重新提交时间时不显示
//     已重新提交；保存了零值重新提交时间仍按已重新提交展示、时间显示
//     未记录，不悄悄改成尚未提交。
func viewReturnRound(r ReturnRound) returnRoundView {
	v := returnRoundView{
		Seq:            r.Seq,
		ReturnedAt:     fmtTimeIfRecorded(r.ReturnedAt),
		ReturnOperator: whoIfRecorded(r.ReturnOperator),
		Reason:         r.Reason,
		Resubmitted:    r.ResubmittedAt != nil,
		ResubmittedAt:  fmtTimePtrIfRecorded(r.ResubmittedAt),
	}
	if r.Supplement != "" {
		v.HasSupplement = true
		v.Supplement = r.Supplement
		v.SupplementOperator = whoIfRecorded(r.SupplementOperator)
		v.SupplementAt = fmtTimePtrIfRecorded(r.SupplementAt)

